head.script:
scwin.strSch;
scwin.gEmpNo;
scwin.gAcptNo; // 접수번호
scwin.gFormUpclssCd; // 공시대분류
scwin.gRsnClsscd; // 사유분류코드
scwin.gMktId; // 시장구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_procinfo",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_procinfo=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 부모창의 데이타 셋팅하기
        scwin.setParamData();

        // 대분류에 해당하는 사유분류리스트  셋팅
        const sbmOptions2 = {
            id : "sbm_dts_Rsnclss",
            action : "/CodeAction.do",
            ref : "",
            target : "dts_Rsnclss=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_modify_OnSuccess
 * @description modify On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_modify_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 저장되었습니다.");
        await $c.win.closePopup();

        // 부모창의  frame_head를  reload 처리해야함
        $c.frame.path("../../frame_head").fn_HeadRead();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10002.trs_modify_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_modify_OnFail
 * @description modify On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_modify_OnFail = async function() {
    try {
        await $c.win.alert('trs_modify.OnFail() :' + trs_modify.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10002.trs_modify_OnFail" });
    }
};

/**
 * @method
 * @name btn_Cancle_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancle_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10002.btn_Cancle_onclick" });
    }
};

/**
 * @method
 * @name dts_Rsnclss_OnLoadCompleted
 * @description dts_Rsnclss 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Rsnclss_OnLoadCompleted = function(rowcount) {
    try {
        // 초기1회 초기값으로 설정된 사유분류를 검색한다.
        if (scwin.strSch !== "") {
            for (let i = 1; i <= dts_Rsnclss.getRowCount(); i++) {
                if (scwin.strSch === dts_Rsnclss.getCellData(i, 1)) {
                    dts_Rsnclss.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strSch = "";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10002.dts_Rsnclss_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Rsnclss_OnLoadError
 * @description dts_Rsnclss 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Rsnclss_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Rsnclss);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10002.dts_Rsnclss_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        dts_procinfo.insertRow();
        dts_procinfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
        dts_procinfo.setCellData(1, "FORM_UPCLSS_CD", scwin.gFormUpclssCd);
        dts_procinfo.setCellData(1, "RSN_CLSS_CD", $c.cp.valueOfIndex(cmb_DisclsRsnClss, "VALUE", cmb_DisclsRsnClss.getSelectedIndex()));
        dts_procinfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
        dts_procinfo.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
        await scwin.modifyDsclRsnClss();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10002.btn_Save_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name modifyDsclRsnClss
 * @description 수정하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modifyDsclRsnClss = async function() {
    const vTp = cmb_DisclsRsnClss.getValue();
    if (vTp.length < 1) {
        await $c.win.alert("사유분류를 선택하시오.");
        cmb_DisclsRsnClss.focus();
        return;
    }
    const vAnswer = confirm('사유분류를 변경하시겠습니까?');
    if (vAnswer === true) {
        trs_modify.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_modify",
            action : "/DisclosureStudy.do",
            ref : "dts_procinfo",
            target : "trs_modify=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParamData
 * @description 부모창의 frame_head 데이타 셋팅하기
 * @returns {void}
 * @hidden N
 */
scwin.setParamData = function() {
    /*
    		gFormUpclssCd = frame.Provider("../").dts_AcptProcs.NameString(1, 'FORM_UPCLSS_CD');
    		gRsnClsscd = frame.Provider("../").dts_AcptProcs.NameString(1, 'RSN_CLSS_CD');
    		gAcptNo = frame.Provider("../").dts_AcptProcs.NameString(1, 'ACPT_NO');
    		gMktId = frame.Provider("../").dts_AcptProcs.NameString(1, 'MKT_ID');
     */
    scwin.gFormUpclssCd = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'FORM_UPCLSS_CD');
    scwin.gRsnClsscd = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'RSN_CLSS_CD');
    scwin.gAcptNo = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'ACPT_NO');
    scwin.gMktId = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'MKT_ID');
    scwin.strSch = scwin.gRsnClsscd;
    scwin.gEmpNo = js_emp_no; // 세션정보

};
